@Component({
  selector: 'app-tarjeta-tarea',
  template: `
    <article>
      <h3>{{ titulo }}</h3>
      <p>Responsable: {{ responsable }}</p>
    </article>
  `,
  styles: `article { border: 1px solid #ccc; padding: 8px; }`,
})
export class TarjetaTarea {
  titulo = 'Configurar CI';
  responsable = 'Ana';
}

